     7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import {
    13→  Page,
    14→  Layout,
    15→  Card,
    16→  BlockStack,
    17→  InlineStack,
    18→  InlineGrid,
    19→  Text,
    20→  Button,
    21→  TextField,
    22→  Select,
    23→  Checkbox,
    24→  Divider,
    25→  Box,
    26→  Banner,
    27→} from "@shopify/polaris";
    28→
    29→export const loader = async ({ request }: LoaderFunctionArgs) => {
    30→  const { session } = await authenticate.admin(request);
    31→  const shop = session.shop;
    32→
    33→  let config = await db.widgetConfig.findUnique({ where: { shop } });
    34→
    35→  if (!config) {
    36→    config = await db.widgetConfig.create({ data: { shop } });
    37→  }
    38→
    39→  const appUrl = process.env.SHOPIFY_APP_URL || "";
    40→  const themeEditorUrl = `https://${shop}/admin/themes/current/editor`;
    41→
    42→  return { config, appUrl, themeEditorUrl };
    43→};
    44→
    45→export const action = async ({ request }: ActionFunctionArgs) => {
    46→  const { session } = await authenticate.admin(request);
    47→  const shop = session.shop;
    48→  const formData = await request.formData();
    49→  const intent = formData.get("intent");
    50→
    51→  if (intent === "save") {
    52→    const data = {
    53→      position: String(formData.get("position") || "inline"),
    54→      primaryColor: String(formData.get("primaryColor") || "#008060"),
    55→      successColor: String(formData.get("successColor") || "#008060"),
    56→      errorColor: String(formData.get("errorColor") || "#D72C0D"),
    57→      backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
    58→      textColor: String(formData.get("textColor") || "#202223"),
    59→      heading: String(formData.get("heading") || "Check Delivery Availability"),
    60→      placeholder: String(formData.get("placeholder") || "Enter your zip code"),
    61→      buttonText: String(formData.get("buttonText") || "Check"),
    62→      successMessage: String(
    63→        formData.get("successMessage") ||
    64→          "Great news! We deliver to your area.",
    65→      ),
    66→      errorMessage: String(
    67→        formData.get("errorMessage") ||
    68→          "Sorry, we don't deliver to this area yet.",
    69→      ),
    70→      notFoundMessage: String(
    71→        formData.get("notFoundMessage") ||
    72→          "This zip code was not found in our system.",
    73→      ),
    74→      showEta: formData.get("showEta") === "true",
    75→      showZone: formData.get("showZone") === "true",
    76→      showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
    77→      borderRadius: String(formData.get("borderRadius") || "8"),
    78→      customCss: String(formData.get("customCss") || "") || null,
    79→    };
    80→
    81→    await db.widgetConfig.upsert({
    82→      where: { shop },
    83→      create: { shop, ...data },
    84→      update: data,
    85→    });
    86→
    87→    return { success: true };
    88→  }
    89→
    90→  if (intent === "reset") {
    91→    await db.widgetConfig.upsert({
    92→      where: { shop },
    93→      create: { shop },
    94→      update: {
    95→        position: "inline",
    96→        primaryColor: "#008060",
    97→        successColor: "#008060",
    98→        errorColor: "#D72C0D",
    99→        backgroundColor: "#FFFFFF",
   100→        textColor: "#202223",
   101→        heading: "Check Delivery Availability",
   102→        placeholder: "Enter your zip code",
   103→        buttonText: "Check",
   104→        successMessage: "Great news! We deliver to your area.",
   105→        errorMessage: "Sorry, we don't deliver to this area yet.",
   106→        notFoundMessage: "This zip code was not found in our system.",
   107→        showEta: true,
   108→        showZone: false,
   109→        showWaitlistOnFailure: false,
   110→        borderRadius: "8",
   111→        customCss: null,
   112→      },
   113→    });
   114→    return { success: true, action: "reset" };
   115→  }
   116→
   117→  return null;
   118→};
   119→
   120→type WidgetConfig = {
   121→  position: string;
   122→  primaryColor: string;
   123→  successColor: string;
   124→  errorColor: string;
   125→  backgroundColor: string;
   126→  textColor: string;
   127→  heading: string;
   128→  placeholder: string;
   129→  buttonText: string;
   130→  successMessage: string;
   131→  errorMessage: string;
   132→  notFoundMessage: string;
   133→  showEta: boolean;
   134→  showZone: boolean;
   135→  showWaitlistOnFailure: boolean;
   136→  borderRadius: string;
   137→  customCss: string | null;
   138→};
