   159→  const [errorMessage, setErrorMessage] = useState(c.errorMessage);
   160→  const [notFoundMessage, setNotFoundMessage] = useState(c.notFoundMessage);
   161→  const [showEta, setShowEta] = useState(c.showEta);
   162→  const [showZone, setShowZone] = useState(c.showZone);
   163→  const [showWaitlistOnFailure, setShowWaitlistOnFailure] = useState(
