   190→    fd.set("textColor", textColor);
   191→    fd.set("heading", heading);
   192→    fd.set("placeholder", placeholder);
   193→    fd.set("buttonText", buttonText);
   194→    fd.set("successMessage", successMessage);
   195→    fd.set("errorMessage", errorMessage);
   196→    fd.set("notFoundMessage", notFoundMessage);
   197→    fd.set("showEta", String(showEta));
   198→    fd.set("showZone", String(showZone));
   199→    fd.set("showWaitlistOnFailure", String(showWaitlistOnFailure));
   200→    fd.set("borderRadius", borderRadius);
   201→    fd.set("customCss", customCss);
   202→    fetcher.submit(fd, { method: "POST" });
   203→    shopify.toast.show("Widget settings saved");
   204→  }, [
   205→    position,
   206→    primaryColor,
   207→    successColor,
   208→    errorColor,
   209→    backgroundColor,
   210→    textColor,
   211→    heading,
   212→    placeholder,
   213→    buttonText,
   214→    successMessage,
   215→    errorMessage,
   216→    notFoundMessage,
   217→    showEta,
   218→    showZone,
   219→    showWaitlistOnFailure,
   220→    borderRadius,
   221→    customCss,
   222→    fetcher,
   223→    shopify,
   224→  ]);
   225→
   226→  const handleReset = useCallback(() => {
