   117→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
   118→      '<div class="zcc-row">' +
   119→        '<input class="zcc-input" type="text" id="' + WID + '-inp"' +
   120→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
   121→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
   122→        '<button class="zcc-btn" id="' + WID + '-btn" type="button">' + esc(cfg.buttonText) + "</button>" +
   123→      "</div>" +
   124→      '<div id="' + WID + '-res"></div>';
   125→
   126→    var inp = document.getElementById(WID + "-inp");
   127→    var btn = document.getElementById(WID + "-btn");
   128→    var res = document.getElementById(WID + "-res");
   129→    var btnLabel = cfg.buttonText;
   130→
   131→    function checkZip() {
   132→      var zip = inp.value.trim();
   133→      if (!zip) { inp.focus(); return; }
   134→
   135→      btn.disabled = true;
   136→      btn.textContent = "\u2026";
   137→      res.innerHTML = "";
   138→
   139→      fetch(
   140→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
   141→          "&zip=" + encodeURIComponent(zip)
   142→      )
   143→        .then(function (r) { return r.json(); })
   144→        .then(function (data) {
   145→          btn.disabled = false;
   146→          btn.textContent = btnLabel;
   147→
   148→          if (data.allowed) {
   149→            var html = '<div class="zcc-result ok">' + esc(data.message);
   150→            if (cfg.showEta && data.eta) {
   151→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
   152→            }
   153→            if (cfg.showZone && data.zone) {
   154→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
   155→            }
   156→            html += "</div>";
   157→            res.innerHTML = html;
   158→          } else {
   159→            var html = '<div class="zcc-result fail">' + esc(data.message);
   160→            if (cfg.showWaitlistOnFailure) {
   161→              html +=
   162→                '<div class="zcc-wl">' +
   163→                '<input class="zcc-wl-input" type="email" id="' + WID + '-wl-email" placeholder="Enter email to join waitlist" />' +
   164→                '<button class="zcc-wl-btn" id="' + WID + '-wl-btn" type="button">Join Waitlist</button>' +
   165→                "</div>";
   166→            }
   167→            html += "</div>";
   168→            res.innerHTML = html;
   169→
   170→            if (cfg.showWaitlistOnFailure) {
   171→              var wBtn = document.getElementById(WID + "-wl-btn");
   172→              if (wBtn) {
   173→                wBtn.addEventListener("click", function () {
   174→                  var emailEl = document.getElementById(WID + "-wl-email");
   175→                  var email = emailEl ? emailEl.value.trim() : "";
   176→                  if (!email) { if (emailEl) emailEl.focus(); return; }
   177→                  joinWaitlist(zip, email, wBtn);
   178→                });
   179→              }
   180→            }
   181→          }
   182→        })
   183→        .catch(function () {
   184→          btn.disabled = false;
   185→          btn.textContent = btnLabel;
   186→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
   187→        });
   188→    }
   189→
   190→    function joinWaitlist(zip, email, wBtn) {
   191→      wBtn.disabled = true;
   192→      wBtn.textContent = "Joining\u2026";
   193→
   194→      fetch(API_BASE + "/api/waitlist", {
   195→        method: "POST",
   196→        headers: { "Content-Type": "application/json" },
   197→        body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
   198→      })
   199→        .then(function (r) { return r.json(); })
   200→        .then(function (data) {
   201→          var wlEl = wBtn.closest(".zcc-wl");
   202→          if (data.success) {
   203→            if (wlEl) wlEl.innerHTML =
   204→              '<p style="font-size:13px;margin:6px 0 0">' +
   205→              "\u2713 You\u2019ve been added to the waitlist!" +
   206→              "</p>";
   207→          } else {
   208→            wBtn.disabled = false;
   209→            wBtn.textContent = "Join Waitlist";
   210→          }
   211→        })
   212→        .catch(function () {
   213→          wBtn.disabled = false;
   214→          wBtn.textContent = "Join Waitlist";
   215→        });
   216→    }
   217→
   218→    btn.addEventListener("click", checkZip);
   219→    inp.addEventListener("keydown", function (e) {
   220→      if (e.key === "Enter") checkZip();
   221→    });
   222→  }
   223→
   224→  function esc(str) {
   225→    return String(str)
   226→      .replace(/&/g, "&amp;")
   227→      .replace(/</g, "&lt;")
   228→      .replace(/>/g, "&gt;")
   229→      .replace(/"/g, "&quot;");
   230→  }
   231→
   232→  function escAttr(str) {
   233→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
   234→  }
   235→})();
